  const spark = (x, y, s, c = "#fff") => `<path d="M${x},${y - s} Q${x},${y} ${x + s},${y} Q${x},${y} ${x},${y + s} Q${x},${y} ${x - s},${y} Q${x},${y} ${x},${y - s}Z" fill="${c}"/>`;
  const spiky = (cx, cy, rx, ry, n, k, a0 = 0, a1 = 360) => { let d = ""; for (let i = 0; i <= n * 2; i++) { const a = (a0 + (a1 - a0) * i / (n * 2)) * Math.PI / 180, q = i % 2 ? 1 + k : 1; d += (i ? "L" : "M") + (cx + rx * q * Math.cos(a)).toFixed(1) + "," + (cy + ry * q * Math.sin(a)).toFixed(1); } return d + "Z"; };
  const scal = (cx, cy, rx, ry, n, k = 1) => { let d = ""; for (let i = 0; i <= n; i++) { const a = i / n * Math.PI * 2 - 1.57, x = cx + rx * Math.cos(a), y = cy + ry * Math.sin(a), r = Math.PI * (rx + ry) / 2 / n * 1.08 * k; d += i ? `A${r.toFixed(1)},${r.toFixed(1)} 0 0 1 ${x.toFixed(1)},${y.toFixed(1)}` : `M${x.toFixed(1)},${y.toFixed(1)}`; } return d + "Z"; };

