  const whisk = (y, c = "#8a7a80") => two(N(`M74,${y} L46,${y - 5} M74,${y + 6} L47,${y + 8}`, c, 1.4, 'opacity=".75"'));
  const tongue = y => P(`M93,${y} Q100,${y + 3} 107,${y} L106,${y + 10} Q100,${y + 17} 94,${y + 10}Z`, "#f7889b", "#b0475e", 1.6) + N(`M100,${y + 3} V${y + 10}`, "#b0475e", 1.2);
  // contours : jamais noirs, toujours dérivés de la fourrure
